insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', '996f0428-05be-51ff-8861-9f4361f62762', 'aaa03cf0-2450-5e71-bea2-63ffca71d26d', '74b2db6a-ba04-52cb-a079-d69a0ee5cc78', 'Life Processes', 'Nine marks and one of the most predictable chapters in the paper.') on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('b8e88f1a-74bc-5ff0-8a8a-cd398d9e9eed', 'b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', 'The opening and closing of stomata is controlled by:', null, '["Chlorophyll","Guard cells","Xylem","Lenticels"]'::jsonb, 1, 'Guard cells swell when water enters, opening the pore, and shrink when water leaves, closing it. Label this correctly in the diagram — the diagram alone is often worth a mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('55490ba1-d35e-5556-9cff-f0ad1168bef7', 'b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', 'The correct sequence of the human digestive tract is:', null, '["Mouth → oesophagus → stomach → small intestine → large intestine","Mouth → stomach → oesophagus → small intestine → large intestine","Mouth → oesophagus → small intestine → stomach → large intestine","Mouth → stomach → small intestine → oesophagus → large intestine"]'::jsonb, 0, 'Food passes down the oesophagus into the stomach, then the small intestine where most absorption happens, then the large intestine where water is absorbed.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('c7577f28-d841-5449-96d8-80813b712427', 'b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', 'Why do the walls of the left ventricle appear thicker than those of the other chambers?', null, '["It stores more blood","It must pump blood to the whole body at high pressure","It receives blood from the lungs","It contains valves"]'::jsonb, 1, 'The left ventricle pumps oxygenated blood into the aorta and around the entire body, so it needs more muscular force. The right ventricle only pumps to the lungs, which are nearby.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('8a693288-50aa-5aac-b52c-01d4e765c446', 'b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', 'The functional unit of the kidney is the:', null, '["Neuron","Nephron","Alveolus","Villus"]'::jsonb, 1, 'Nephron — kidney. Neuron — nervous system. Alveolus — lungs. Villus — small intestine. These four are deliberately confused in MCQs, so keep them separated.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('49644998-6a2d-5210-ab47-973159b41539', 'b0c7d3ec-e7ef-51a3-ad6c-f7bf21a01b5a', 'Identify the process and explain the observation.', 'A potted plant is kept in the dark for 48 hours, then one leaf is partly covered with black paper and the plant is placed in sunlight for six hours. The leaf is tested with iodine.', '["The whole leaf turns blue-black because starch is present throughout","Only the uncovered part turns blue-black, showing light is necessary for photosynthesis","Only the covered part turns blue-black","No part turns blue-black because the plant was destarched"]'::jsonb, 1, 'Destarching first removes existing starch, so any starch found afterwards must be newly made. Only the part that received light makes starch, so only that part turns blue-black with iodine. The experiment proves light is essential.', 3, 'medium', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.session_subjects (id, session_id, subject_id, chapter_id, chapter_name, focus_topic, estimated_minutes, sort_order) values ('e8f11326-cec0-5a7f-a44a-4b62f700b734', '6411ceb4-1ecf-55de-a456-3240c157d013', '6ccda25c-d4bb-5634-9e3a-c7cb8e50bb85', '05b8c4f0-5e47-5478-81aa-111444e31adf', 'व्याकरण — समास, अलंकार, मुहावरे', 'Finish व्याकरण — समास, अलंकार, मुहावरे — remaining questions, then practice and summary.', 30, 3) on conflict (id) do update set focus_topic = excluded.focus_topic, estimated_minutes = excluded.estimated_minutes;
