insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('b1daa0e0-a191-5234-8b9a-e5594f8ec1d5', 'b0588eb2-b7cf-5280-ab2f-836e77adfbd1', 'The opening and closing of stomata is controlled by:', null, '["Chlorophyll","Guard cells","Xylem","Lenticels"]'::jsonb, 1, 'Guard cells swell when water enters, opening the pore, and shrink when water leaves, closing it. Label this correctly in the diagram — the diagram alone is often worth a mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ee7ec2e5-36ce-5fa3-b7bd-183e9bf514d7', 'b0588eb2-b7cf-5280-ab2f-836e77adfbd1', 'The correct sequence of the human digestive tract is:', null, '["Mouth → oesophagus → stomach → small intestine → large intestine","Mouth → stomach → oesophagus → small intestine → large intestine","Mouth → oesophagus → small intestine → stomach → large intestine","Mouth → stomach → small intestine → oesophagus → large intestine"]'::jsonb, 0, 'Food passes down the oesophagus into the stomach, then the small intestine where most absorption happens, then the large intestine where water is absorbed.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('c67dd738-6c62-54a5-adcb-9618033c0491', 'b0588eb2-b7cf-5280-ab2f-836e77adfbd1', 'Why do the walls of the left ventricle appear thicker than those of the other chambers?', null, '["It stores more blood","It must pump blood to the whole body at high pressure","It receives blood from the lungs","It contains valves"]'::jsonb, 1, 'The left ventricle pumps oxygenated blood into the aorta and around the entire body, so it needs more muscular force. The right ventricle only pumps to the lungs, which are nearby.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('79740a58-c608-53e3-9aa7-492de582dfc7', 'b0588eb2-b7cf-5280-ab2f-836e77adfbd1', 'The functional unit of the kidney is the:', null, '["Neuron","Nephron","Alveolus","Villus"]'::jsonb, 1, 'Nephron — kidney. Neuron — nervous system. Alveolus — lungs. Villus — small intestine. These four are deliberately confused in MCQs, so keep them separated.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('a8416f9e-c05b-56ae-9bde-ad1dc4a65ab4', 'b0588eb2-b7cf-5280-ab2f-836e77adfbd1', 'Identify the process and explain the observation.', 'A potted plant is kept in the dark for 48 hours, then one leaf is partly covered with black paper and the plant is placed in sunlight for six hours. The leaf is tested with iodine.', '["The whole leaf turns blue-black because starch is present throughout","Only the uncovered part turns blue-black, showing light is necessary for photosynthesis","Only the covered part turns blue-black","No part turns blue-black because the plant was destarched"]'::jsonb, 1, 'Destarching first removes existing starch, so any starch found afterwards must be newly made. Only the part that received light makes starch, so only that part turns blue-black with iodine. The experiment proves light is essential.', 3, 'medium', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.session_subjects (id, session_id, subject_id, chapter_id, chapter_name, focus_topic, estimated_minutes, sort_order) values ('6d689aef-f49d-523f-aa32-ea1ce1d2ee73', 'ad391c57-a1e1-5d48-a3ab-e8412c80d432', '07df4f0d-abba-593f-a724-cbb0b95bafa0', 'f02fb78d-2d2b-5bd7-aafc-5b93146bbc84', 'Grammar — Tenses, Modals, Subject-Verb Agreement', 'Finish Grammar — Tenses, Modals, Subject-Verb Agreement — remaining questions, then practice and summary.', 25, 2) on conflict (id) do update set focus_topic = excluded.focus_topic, estimated_minutes = excluded.estimated_minutes;
