insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('25aa8487-2141-5b94-8119-f7cc3212918a', '8f4606c5-02fe-5b3c-8456-b37ec61305bb', '07df4f0d-abba-593f-a724-cbb0b95bafa0', '7f1bdba0-98bf-55f9-b10a-8f6eb1048bdb', 'A Letter to God', null) on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('48d99180-157d-510b-a0b8-336b0445d3df', '25aa8487-2141-5b94-8119-f7cc3212918a', 'Lencho described the raindrops as:', null, '["Pearls","New coins","Silver drops","Diamonds"]'::jsonb, 1, 'He compares the big drops to ten-cent pieces and the small ones to five-cent pieces, because to him rain means money from a good harvest. Quoting the exact image earns the mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('f1218fb2-fe94-59eb-995e-f3db288920f0', '25aa8487-2141-5b94-8119-f7cc3212918a', 'Why did Lencho call the post office employees "a bunch of crooks"?', null, '["They lost his letter","He believed they had stolen the rest of the money he had asked God for","They refused to help him","They laughed at him"]'::jsonb, 1, 'He received only 70 pesos of the 100 he asked for, and since his faith in God was absolute, the only explanation he could accept was that the post office had taken the rest. The irony — the money came from those very employees — is the point of the story.', 2, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('37a8c06c-93a1-5a84-aae8-b62e86eb3fa9', '25aa8487-2141-5b94-8119-f7cc3212918a', 'The postmaster arranged the money because he:', null, '["Feared Lencho","Did not want to shake Lencho’s faith","Was ordered to","Knew Lencho personally"]'::jsonb, 1, 'He was moved by the depth of Lencho’s faith and acted to protect it. Mention both his kindness and his wish to preserve that faith for full marks.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('a576124d-e092-5d52-9762-7600053c5b5b', '25aa8487-2141-5b94-8119-f7cc3212918a', 'The main theme of the story is:', null, '["The cruelty of nature","Unquestioning faith, and human generosity","The importance of farming","Corruption in the postal service"]'::jsonb, 1, 'The story contrasts Lencho’s blind faith with the quiet goodness of the people who actually helped him. Theme questions want both halves, not just one.', 2, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('a0981044-5b11-5c78-8821-fa27160f3151', '25aa8487-2141-5b94-8119-f7cc3212918a', '"The hailstorm left the field white, as if covered with salt." This is an example of:', null, '["Metaphor","Simile","Personification","Alliteration"]'::jsonb, 1, 'The comparison uses "as if", which makes it a simile. A metaphor would state it directly without "like" or "as".', 1, 'easy', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.sessions (id, session_number, scheduled_date, phase, title, summary, focus_topics) values ('0d9cd24d-a387-5212-81f5-b4885fc3e6a1', 24, '2025-10-28', 'foundation', 'Day 24 — Triangles + Sectors of the Indian Economy', 'About 2.5 hours today. Maths first while your head is fresh.', array['Maths: Triangles', 'SSt: Sectors of the Indian Economy', 'Hindi: क्षितिज — नेताजी का चश्मा']) on conflict (id) do update set title = excluded.title, summary = excluded.summary, focus_topics = excluded.focus_topics;
