insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', '2857c215-cab1-5b1f-b5b9-22f44ed64c4e', 'aaa03cf0-2450-5e71-bea2-63ffca71d26d', '656773ad-9362-50c0-a103-98aa010d2f40', 'Light — Reflection and Refraction', 'Ten marks, and the sign convention is where most of them are lost.') on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('0389e9a6-b3ed-5ad0-b359-ff91e9309a99', '5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', 'The focal length of a concave mirror of radius of curvature 20 cm is:', null, '["5 cm","10 cm","20 cm","40 cm"]'::jsonb, 1, 'f = R/2 = 10 cm. For a concave mirror both f and R are negative by the sign convention, so in a numerical you would write f = −10 cm.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('20eff24b-d915-5004-9d4c-759482707a08', '5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', 'An object is placed at the centre of curvature of a concave mirror. The image is:', null, '["Virtual, erect and magnified","Real, inverted and the same size","Real, inverted and diminished","At infinity"]'::jsonb, 1, 'At C the image forms at C, real, inverted and the same size. Learn the six positions as a table — these MCQs are free marks once the table is memorised.', 1, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('7abda504-af27-59e5-82bc-289660249dd3', '5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', 'A lens has a power of −2.5 D. It is:', null, '["A convex lens of focal length 40 cm","A concave lens of focal length 40 cm","A convex lens of focal length 25 cm","A concave lens of focal length 25 cm"]'::jsonb, 1, 'P = 1/f in metres, so f = 1/(−2.5) = −0.4 m = −40 cm. Negative power means a concave (diverging) lens.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('cf9d6cd7-32c3-59b7-bd97-ff85dc5f483b', '5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', 'Light travelling from water into air bends:', null, '["Towards the normal","Away from the normal","Along the normal","It does not bend"]'::jsonb, 1, 'Going from a denser to a rarer medium, light bends away from the normal. Denser to rarer — away; rarer to denser — towards.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('32e48bab-92ee-5aab-8121-1d4668b78b3a', '5739b0cb-99ef-5b3c-86d0-3aabc659f2f1', 'Assertion (A): A convex mirror is used as a rear-view mirror in vehicles. Reason (R): A convex mirror always forms a virtual, erect and diminished image with a wide field of view.', null, '["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"]'::jsonb, 0, 'Both are true and R is precisely why A is done. The wide field of view is the key phrase the marking scheme looks for.', 1, 'medium', 'assertion_reason', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
