insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', '70cbb773-4531-5dd5-b703-d4f5a75e5dc3', 'aaa03cf0-2450-5e71-bea2-63ffca71d26d', '656773ad-9362-50c0-a103-98aa010d2f40', 'Light — Reflection and Refraction', 'Ten marks, and the sign convention is where most of them are lost.') on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('625d71eb-bc61-5f60-8e49-73a3259f49c2', '1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', 'The focal length of a concave mirror of radius of curvature 20 cm is:', null, '["5 cm","10 cm","20 cm","40 cm"]'::jsonb, 1, 'f = R/2 = 10 cm. For a concave mirror both f and R are negative by the sign convention, so in a numerical you would write f = −10 cm.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ac69e56b-3bb0-51b1-84dd-22ac138a3d39', '1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', 'An object is placed at the centre of curvature of a concave mirror. The image is:', null, '["Virtual, erect and magnified","Real, inverted and the same size","Real, inverted and diminished","At infinity"]'::jsonb, 1, 'At C the image forms at C, real, inverted and the same size. Learn the six positions as a table — these MCQs are free marks once the table is memorised.', 1, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('e0c8e535-6de1-512e-bc8f-74962731e3b7', '1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', 'A lens has a power of −2.5 D. It is:', null, '["A convex lens of focal length 40 cm","A concave lens of focal length 40 cm","A convex lens of focal length 25 cm","A concave lens of focal length 25 cm"]'::jsonb, 1, 'P = 1/f in metres, so f = 1/(−2.5) = −0.4 m = −40 cm. Negative power means a concave (diverging) lens.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('eaf57760-66d2-56e0-b0f5-bb92978d5d90', '1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', 'Light travelling from water into air bends:', null, '["Towards the normal","Away from the normal","Along the normal","It does not bend"]'::jsonb, 1, 'Going from a denser to a rarer medium, light bends away from the normal. Denser to rarer — away; rarer to denser — towards.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('962e948c-46b4-5918-843e-39e08c7b29e3', '1fb1e2b7-7579-558b-bcec-80ded2c0d7eb', 'Assertion (A): A convex mirror is used as a rear-view mirror in vehicles. Reason (R): A convex mirror always forms a virtual, erect and diminished image with a wide field of view.', null, '["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"]'::jsonb, 0, 'Both are true and R is precisely why A is done. The wide field of view is the key phrase the marking scheme looks for.', 1, 'medium', 'assertion_reason', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
