insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('103a74ba-3996-525c-834c-a32cb406753a', '116fecd4-be1b-5568-a393-051c34d26eb0', '9d8d5c4d-3c0e-5b0c-b895-3a70710ff2e4', '772b51b8-fc58-5074-b438-d056e477db2a', 'Polynomials', null) on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('0fd9a0d6-c61e-55ae-aeec-f97e130ed720', '103a74ba-3996-525c-834c-a32cb406753a', 'If α and β are the zeroes of x² − 5x + 6, then α + β and αβ are:', null, '["5 and 6","−5 and 6","5 and −6","6 and 5"]'::jsonb, 0, 'For ax² + bx + c, sum of zeroes = −b/a = 5 and product = c/a = 6. Watch the sign on −b/a; that single minus sign costs marks every year.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('9c460719-0778-5447-919b-e0d1b782d30d', '103a74ba-3996-525c-834c-a32cb406753a', 'The number of zeroes of a polynomial equals the number of points where its graph:', null, '["Crosses the y-axis","Intersects the x-axis","Turns","Is a straight line"]'::jsonb, 1, 'A zero is a value of x where y = 0, which is precisely where the curve meets the x-axis. Graph-reading questions of this type appear almost every year.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('f3c529cb-76d3-51b3-9562-7d5bbf6aa9b7', '103a74ba-3996-525c-834c-a32cb406753a', 'A quadratic polynomial whose zeroes are 3 and −2 is:', null, '["x² − x − 6","x² + x − 6","x² − x + 6","x² + 5x + 6"]'::jsonb, 0, 'Sum = 1, product = −6, so the polynomial is x² − (sum)x + product = x² − x − 6. Always write the general form first; it removes the guesswork.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('3cf94672-6441-500f-88c8-ac205a34f55c', '103a74ba-3996-525c-834c-a32cb406753a', 'If one zero of 2x² − 8x + k is the reciprocal of the other, then k equals:', null, '["2","4","8","1"]'::jsonb, 0, 'Reciprocal zeroes means αβ = 1. Product of zeroes = k/2 = 1, so k = 2.', 2, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('3b723361-3973-5c6a-883d-8f06781e784e', '103a74ba-3996-525c-834c-a32cb406753a', 'A cubic polynomial has at most how many zeroes?', null, '["1","2","3","Unlimited"]'::jsonb, 2, 'A polynomial of degree n has at most n zeroes. Degree 3 therefore gives at most 3.', 1, 'easy', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
