insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('e9a23215-b204-5954-b359-0079637e6e98', 'ed4f8450-7593-5988-9a8e-c2fccf3d20d4', '4e91d7c3-6d76-5229-b8bd-6857078383c3', 'baa613a6-cd15-5448-8f45-8905ba487ede', 'Money and Credit', 'Four marks, but almost always as a case study — so the format matters as much as the content.') on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('d9384186-bdb9-5291-801c-29dd0a5af8e7', 'e9a23215-b204-5954-b359-0079637e6e98', 'Modern currency in India is accepted as a medium of exchange because:', null, '["It is made of precious metal","It is authorised by the Reserve Bank of India and the law","Shopkeepers like it","It can be exchanged for gold on demand"]'::jsonb, 1, 'Rupee notes carry a guarantee from the Central Government, and the RBI issues them under the law. Modern currency has no value of its own — that is exactly the point being tested.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('291f8b2d-7677-5a54-950d-72d14fade454', 'e9a23215-b204-5954-b359-0079637e6e98', 'The main reason formal credit is cheaper than informal credit is that:', null, '["Banks are run by the government","The RBI supervises the rate of interest and lending terms","Moneylenders charge no interest","Formal lenders require no documents"]'::jsonb, 1, 'The RBI monitors formal lenders, so rates stay reasonable. Informal lenders are unsupervised, which is why their high rates push borrowers into debt traps.', 2, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('7283abde-2837-5ff0-9fba-fa9ab4abf556', 'e9a23215-b204-5954-b359-0079637e6e98', 'Collateral is best described as:', null, '["The interest paid on a loan","An asset the borrower owns and uses as a guarantee until the loan is repaid","A document proving income","The instalment amount"]'::jsonb, 1, 'Land, buildings, vehicles, livestock or deposits can all serve as collateral. The lack of collateral is the single biggest reason poor households are shut out of formal credit.', 1, 'easy', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('5a2d57fd-a547-55db-90b2-8644ef9f03ad', 'e9a23215-b204-5954-b359-0079637e6e98', 'What is the most likely outcome, and why?', 'Rani borrows ₹5,000 from a village moneylender at 5% per month to buy seeds. The crop fails because of poor rain. She borrows again the following season to repay the first loan.', '["She benefits because credit always helps farmers","She falls into a debt trap, because the loan did not generate income and the cost of borrowing is very high","The moneylender must waive the loan","Her income rises as a result of the second loan"]'::jsonb, 1, 'Credit helps only when it increases earnings. When the crop fails, repayment becomes impossible and fresh borrowing just deepens the hole — the textbook definition of a debt trap. In a 4-mark answer, say what happened, name the debt trap, give the reason, and suggest formal credit as the remedy.', 4, 'medium', 'case_study', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('93691559-cc76-5f94-bf7a-0c574353a692', 'e9a23215-b204-5954-b359-0079637e6e98', 'Self Help Groups help poor households mainly because they:', null, '["Give free money","Allow members to borrow without collateral at reasonable rates","Are run by the RBI","Replace banks completely"]'::jsonb, 1, 'SHGs pool small savings and lend to members without collateral, and the group itself handles repayment. That is the answer the marking scheme wants, along with the point about women becoming financially self-reliant.', 2, 'medium', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
