insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('8b0ccd2e-4aac-57db-83b6-8a19e2517bc7', '671d602f-1a95-5a22-9b95-9c693c73be27', 'Lencho described the raindrops as:', null, '["Pearls","New coins","Silver drops","Diamonds"]'::jsonb, 1, 'He compares the big drops to ten-cent pieces and the small ones to five-cent pieces, because to him rain means money from a good harvest. Quoting the exact image earns the mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('bb893fca-506d-5e1c-a369-4d9c82e846ba', '671d602f-1a95-5a22-9b95-9c693c73be27', 'Why did Lencho call the post office employees "a bunch of crooks"?', null, '["They lost his letter","He believed they had stolen the rest of the money he had asked God for","They refused to help him","They laughed at him"]'::jsonb, 1, 'He received only 70 pesos of the 100 he asked for, and since his faith in God was absolute, the only explanation he could accept was that the post office had taken the rest. The irony — the money came from those very employees — is the point of the story.', 2, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('a2c5baf9-164d-5b4c-a7bf-9d0cb9391243', '671d602f-1a95-5a22-9b95-9c693c73be27', 'The postmaster arranged the money because he:', null, '["Feared Lencho","Did not want to shake Lencho’s faith","Was ordered to","Knew Lencho personally"]'::jsonb, 1, 'He was moved by the depth of Lencho’s faith and acted to protect it. Mention both his kindness and his wish to preserve that faith for full marks.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ebcc456b-b141-547f-8191-18bab42ff82a', '671d602f-1a95-5a22-9b95-9c693c73be27', 'The main theme of the story is:', null, '["The cruelty of nature","Unquestioning faith, and human generosity","The importance of farming","Corruption in the postal service"]'::jsonb, 1, 'The story contrasts Lencho’s blind faith with the quiet goodness of the people who actually helped him. Theme questions want both halves, not just one.', 2, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('dc2b0bb0-89c8-5a3d-b8bc-53845d05f7ab', '671d602f-1a95-5a22-9b95-9c693c73be27', '"The hailstorm left the field white, as if covered with salt." This is an example of:', null, '["Metaphor","Simile","Personification","Alliteration"]'::jsonb, 1, 'The comparison uses "as if", which makes it a simile. A metaphor would state it directly without "like" or "as".', 1, 'easy', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
