insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('707a4735-edab-5364-8637-3a4b002ae140', 'db4fc8ea-2d7d-5892-9ada-26628e36cd7f', 'If α and β are the zeroes of x² − 5x + 6, then α + β and αβ are:', null, '["5 and 6","−5 and 6","5 and −6","6 and 5"]'::jsonb, 0, 'For ax² + bx + c, sum of zeroes = −b/a = 5 and product = c/a = 6. Watch the sign on −b/a; that single minus sign costs marks every year.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('1e0889b9-2003-5fa4-9222-8a8727f05276', 'db4fc8ea-2d7d-5892-9ada-26628e36cd7f', 'The number of zeroes of a polynomial equals the number of points where its graph:', null, '["Crosses the y-axis","Intersects the x-axis","Turns","Is a straight line"]'::jsonb, 1, 'A zero is a value of x where y = 0, which is precisely where the curve meets the x-axis. Graph-reading questions of this type appear almost every year.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('bf2228b6-4936-5745-98c1-ced272da8960', 'db4fc8ea-2d7d-5892-9ada-26628e36cd7f', 'A quadratic polynomial whose zeroes are 3 and −2 is:', null, '["x² − x − 6","x² + x − 6","x² − x + 6","x² + 5x + 6"]'::jsonb, 0, 'Sum = 1, product = −6, so the polynomial is x² − (sum)x + product = x² − x − 6. Always write the general form first; it removes the guesswork.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('5672be54-b1a2-55cb-b3d5-f03667db5587', 'db4fc8ea-2d7d-5892-9ada-26628e36cd7f', 'If one zero of 2x² − 8x + k is the reciprocal of the other, then k equals:', null, '["2","4","8","1"]'::jsonb, 0, 'Reciprocal zeroes means αβ = 1. Product of zeroes = k/2 = 1, so k = 2.', 2, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('621bf41e-f3fb-5342-b092-fbfe7fa2ea62', 'db4fc8ea-2d7d-5892-9ada-26628e36cd7f', 'A cubic polynomial has at most how many zeroes?', null, '["1","2","3","Unlimited"]'::jsonb, 2, 'A polynomial of degree n has at most n zeroes. Degree 3 therefore gives at most 3.', 1, 'easy', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
