insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('782ebde6-b521-5cf3-b480-6e7557933594', '7af82cd5-daea-5232-8e2b-9bd87f773d7d', 'The opening and closing of stomata is controlled by:', null, '["Chlorophyll","Guard cells","Xylem","Lenticels"]'::jsonb, 1, 'Guard cells swell when water enters, opening the pore, and shrink when water leaves, closing it. Label this correctly in the diagram — the diagram alone is often worth a mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('acf67cd3-ba58-5ae9-bf17-bc7c395714fb', '7af82cd5-daea-5232-8e2b-9bd87f773d7d', 'The correct sequence of the human digestive tract is:', null, '["Mouth → oesophagus → stomach → small intestine → large intestine","Mouth → stomach → oesophagus → small intestine → large intestine","Mouth → oesophagus → small intestine → stomach → large intestine","Mouth → stomach → small intestine → oesophagus → large intestine"]'::jsonb, 0, 'Food passes down the oesophagus into the stomach, then the small intestine where most absorption happens, then the large intestine where water is absorbed.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('e64860f1-76db-5631-bb73-95e7c9a1af13', '7af82cd5-daea-5232-8e2b-9bd87f773d7d', 'Why do the walls of the left ventricle appear thicker than those of the other chambers?', null, '["It stores more blood","It must pump blood to the whole body at high pressure","It receives blood from the lungs","It contains valves"]'::jsonb, 1, 'The left ventricle pumps oxygenated blood into the aorta and around the entire body, so it needs more muscular force. The right ventricle only pumps to the lungs, which are nearby.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('e92fbbaa-8a05-59bf-bace-4815adec9c1f', '7af82cd5-daea-5232-8e2b-9bd87f773d7d', 'The functional unit of the kidney is the:', null, '["Neuron","Nephron","Alveolus","Villus"]'::jsonb, 1, 'Nephron — kidney. Neuron — nervous system. Alveolus — lungs. Villus — small intestine. These four are deliberately confused in MCQs, so keep them separated.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('c6e958bc-ce41-5cdb-be73-bf7400a09f88', '7af82cd5-daea-5232-8e2b-9bd87f773d7d', 'Identify the process and explain the observation.', 'A potted plant is kept in the dark for 48 hours, then one leaf is partly covered with black paper and the plant is placed in sunlight for six hours. The leaf is tested with iodine.', '["The whole leaf turns blue-black because starch is present throughout","Only the uncovered part turns blue-black, showing light is necessary for photosynthesis","Only the covered part turns blue-black","No part turns blue-black because the plant was destarched"]'::jsonb, 1, 'Destarching first removes existing starch, so any starch found afterwards must be newly made. Only the part that received light makes starch, so only that part turns blue-black with iodine. The experiment proves light is essential.', 3, 'medium', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
