insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('7a4ce35c-f592-5443-aaca-a1b21413f6a2', '15a61e84-af0e-5593-be30-81b85528b3d3', 'aaa03cf0-2450-5e71-bea2-63ffca71d26d', '5b20aa01-4e0c-5f13-a7a3-285d572a55d3', 'Chemical Reactions and Equations', null) on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('efb81bf3-5322-54f6-8688-aa2658032b41', '7a4ce35c-f592-5443-aaca-a1b21413f6a2', 'Which of the following is a displacement reaction?', null, '["CaO + H₂O → Ca(OH)₂","Fe + CuSO₄ → FeSO₄ + Cu","2H₂O → 2H₂ + O₂","NaOH + HCl → NaCl + H₂O"]'::jsonb, 1, 'Iron is more reactive than copper, so it displaces copper from copper sulphate. The first is combination, the third decomposition, the fourth neutralisation — know all four names, they are asked directly.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ed613f9d-6743-50d3-8917-dd2239723ed1', '7a4ce35c-f592-5443-aaca-a1b21413f6a2', 'Why is the burning of magnesium ribbon preceded by cleaning it with sandpaper?', null, '["To make it shiny for appearance","To remove the protective layer of magnesium oxide","To reduce its mass","To make it thinner so it burns faster"]'::jsonb, 1, 'Magnesium reacts with air to form a layer of MgO on its surface, which prevents burning. Removing it exposes clean metal. This is a standard 2-mark question — the words "protective layer of magnesium oxide" are the marking keywords.', 2, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('e5382d6c-5989-5054-8b1f-7c04e37e5ea4', '7a4ce35c-f592-5443-aaca-a1b21413f6a2', 'In the reaction 3Fe + 4H₂O → Fe₃O₄ + 4H₂, the substance being oxidised is:', null, '["Fe","H₂O","Fe₃O₄","H₂"]'::jsonb, 0, 'Iron gains oxygen, so iron is oxidised and water is the oxidising agent. Oxidation = gain of oxygen or loss of hydrogen.', 1, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('2fb284e3-3bf9-518a-9bdf-dd251a6b3ca5', '7a4ce35c-f592-5443-aaca-a1b21413f6a2', 'Assertion (A): Chemical equations must be balanced. Reason (R): Matter can neither be created nor destroyed in a chemical reaction.', null, '["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"]'::jsonb, 0, 'Both true, and the law of conservation of mass is exactly why balancing is required. R explains A, so the first option.', 1, 'easy', 'assertion_reason', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('2bb072fb-737c-5704-aadc-bcf297c9d5a5', '7a4ce35c-f592-5443-aaca-a1b21413f6a2', 'What change would you observe, and why?', 'A white salt is heated strongly in a test tube. It turns yellow while hot, reverts to white on cooling, and a gas with the smell of burning sulphur is released.', '["The salt is zinc carbonate and the gas is CO₂","The salt is zinc sulphate; the yellow-while-hot, white-when-cold change is characteristic of zinc oxide","The salt is lead nitrate and the gas is NO₂","The salt is calcium carbonate and the gas is SO₂"]'::jsonb, 1, 'Zinc oxide is yellow when hot and white when cold — a classic identification point. The sulphur smell indicates SO₂, so the original salt was a sulphate. Lead nitrate gives brown fumes, not a sulphur smell.', 3, 'hard', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
