insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('68bb473f-73b7-5993-940a-6936c61c1c52', 'e9ab59f6-42a0-5373-925b-85ced4af4813', 'कैप्टन चश्मेवाला नेताजी की मूर्ति पर चश्मा क्यों लगाता था?', null, '["पैसे कमाने के लिए","देशभक्ति और नेताजी के प्रति सम्मान के कारण","नगरपालिका के आदेश पर","मूर्तिकार के कहने पर"]'::jsonb, 1, 'कैप्टन के मन में नेताजी के प्रति गहरा सम्मान था। मूर्ति बिना चश्मे के अधूरी लगती थी, इसलिए वह अपनी दुकान से चश्मा लगा देता था। उत्तर में "देशभक्ति" शब्द अवश्य आना चाहिए।', 2, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('04e013ce-e4ed-5929-a34f-ee3ed6799e06', 'e9ab59f6-42a0-5373-925b-85ced4af4813', 'हालदार साहब हर बार मूर्ति देखकर क्या अनुभव करते थे?', null, '["क्रोध","कौतूहल और प्रसन्नता","उदासीनता","भय"]'::jsonb, 1, 'मूर्ति पर हर बार अलग चश्मा देखकर उन्हें कौतूहल होता था और इस छोटी-सी बात में छिपी देशभक्ति देखकर प्रसन्नता भी।', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('91cb5792-14c1-57b9-9773-08f329069056', 'e9ab59f6-42a0-5373-925b-85ced4af4813', 'मूर्ति में सबसे बड़ी कमी क्या थी?', null, '["मूर्ति छोटी थी","चश्मा संगमरमर का नहीं बना था","मूर्ति टूटी हुई थी","मूर्ति का रंग फीका था"]'::jsonb, 1, 'मूर्तिकार चश्मा नहीं बना पाया था, इसलिए मूर्ति की आँखों पर चश्मा नहीं था — यही कमी कैप्टन पूरी करता था।', 1, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('10e49c7f-daa0-5d1a-8576-85317e495b6b', 'e9ab59f6-42a0-5373-925b-85ced4af4813', 'पाठ के अंत में मूर्ति पर सरकंडे का चश्मा देखकर हालदार साहब की आँखें क्यों भर आईं?', null, '["कैप्टन की मृत्यु के कारण","यह देखकर कि देशभक्ति की भावना बच्चों में भी जीवित है","मूर्ति टूट गई थी","चश्मा सस्ता था"]'::jsonb, 1, 'कैप्टन के न रहने पर भी किसी बालक ने सरकंडे का चश्मा लगा दिया था। इससे पता चलता है कि देशभक्ति की परंपरा समाप्त नहीं हुई — यही पाठ का केंद्रीय भाव है।', 3, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('943a937c-8eb2-5f9c-a32e-c189faa48c1d', 'e9ab59f6-42a0-5373-925b-85ced4af4813', 'इस पाठ का मुख्य संदेश क्या है?', null, '["व्यापार करना चाहिए","देशभक्ति किसी भी रूप और किसी भी उम्र में प्रकट हो सकती है","मूर्तियाँ बनानी चाहिए","चश्मा पहनना आवश्यक है"]'::jsonb, 1, 'लेखक बताते हैं कि देशभक्ति दिखावे की नहीं, छोटे-छोटे कार्यों की वस्तु है। कैप्टन जैसा साधारण व्यक्ति भी सच्चा देशभक्त हो सकता है।', 2, 'medium', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
