insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('f3f245d6-60fc-5ca5-a952-e296312160fa', 'ce1acf71-9835-5cdf-8532-381a38c57ffe', '07df4f0d-abba-593f-a724-cbb0b95bafa0', '7f1bdba0-98bf-55f9-b10a-8f6eb1048bdb', 'A Letter to God', null) on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('a3ab3ac2-51c2-563b-9034-559ca8dbaae5', 'f3f245d6-60fc-5ca5-a952-e296312160fa', 'Lencho described the raindrops as:', null, '["Pearls","New coins","Silver drops","Diamonds"]'::jsonb, 1, 'He compares the big drops to ten-cent pieces and the small ones to five-cent pieces, because to him rain means money from a good harvest. Quoting the exact image earns the mark.', 1, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ce9f2b92-56eb-59b8-bc15-8ef8b9884632', 'f3f245d6-60fc-5ca5-a952-e296312160fa', 'Why did Lencho call the post office employees "a bunch of crooks"?', null, '["They lost his letter","He believed they had stolen the rest of the money he had asked God for","They refused to help him","They laughed at him"]'::jsonb, 1, 'He received only 70 pesos of the 100 he asked for, and since his faith in God was absolute, the only explanation he could accept was that the post office had taken the rest. The irony — the money came from those very employees — is the point of the story.', 2, 'medium', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('5a755294-2263-5765-977e-5df4b4638d62', 'f3f245d6-60fc-5ca5-a952-e296312160fa', 'The postmaster arranged the money because he:', null, '["Feared Lencho","Did not want to shake Lencho’s faith","Was ordered to","Knew Lencho personally"]'::jsonb, 1, 'He was moved by the depth of Lencho’s faith and acted to protect it. Mention both his kindness and his wish to preserve that faith for full marks.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('fbd92091-619a-5f87-a34f-cdd623fb88d9', 'f3f245d6-60fc-5ca5-a952-e296312160fa', 'The main theme of the story is:', null, '["The cruelty of nature","Unquestioning faith, and human generosity","The importance of farming","Corruption in the postal service"]'::jsonb, 1, 'The story contrasts Lencho’s blind faith with the quiet goodness of the people who actually helped him. Theme questions want both halves, not just one.', 2, 'medium', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('d73dbcb4-996e-56fd-9105-5fdcc3c4889d', 'f3f245d6-60fc-5ca5-a952-e296312160fa', '"The hailstorm left the field white, as if covered with salt." This is an example of:', null, '["Metaphor","Simile","Personification","Alliteration"]'::jsonb, 1, 'The comparison uses "as if", which makes it a simile. A metaphor would state it directly without "like" or "as".', 1, 'easy', 'mcq', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
