insert into public.quizzes (id, session_subject_id, subject_id, chapter_id, title, description) values ('780256f7-74e7-5c1b-9d3c-8459318b502f', 'bf8898f4-f540-51b2-9a7e-c32be3e52bf3', '9d8d5c4d-3c0e-5b0c-b895-3a70710ff2e4', '48b9999f-0a40-556e-95d6-5166881de186', 'Real Numbers', 'Six marks in the paper. Short, scoring, and worth getting fully right.') on conflict (id) do update set title = excluded.title;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('ef6a18d2-3445-57ec-a214-d7ad47c07259', '780256f7-74e7-5c1b-9d3c-8459318b502f', 'The HCF of 96 and 404 is 4. What is their LCM?', null, '["9696","2424","4848","404"]'::jsonb, 0, 'HCF × LCM = product of the two numbers. 96 × 404 = 38784, and 38784 ÷ 4 = 9696. This identity only works for two numbers — do not try it with three.', 2, 'easy', 'mcq', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('4c6beb71-69b7-5025-a39f-68bea35c5684', '780256f7-74e7-5c1b-9d3c-8459318b502f', 'The decimal expansion of 13/3125 will:', null, '["Be non-terminating repeating","Terminate","Be irrational","Not exist"]'::jsonb, 1, '3125 = 5⁵, which is of the form 2ⁿ5ᵐ. A fraction in lowest terms terminates exactly when its denominator has only 2s and 5s as prime factors.', 1, 'easy', 'mcq', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('2a48b411-a16f-5b12-83b6-12a8d98fbb17', '780256f7-74e7-5c1b-9d3c-8459318b502f', 'If a number ends with the digit 0, it must be divisible by:', null, '["Only 2","Only 5","Both 2 and 5","Neither"]'::jsonb, 2, 'Ending in 0 means the number has 10 as a factor, and 10 = 2 × 5. This is the standard setup for "can 6ⁿ end in 0?" questions — 6ⁿ has no factor of 5, so it cannot.', 1, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('552cb0a4-aeb6-5869-8637-4ab9a1a0a34a', '780256f7-74e7-5c1b-9d3c-8459318b502f', 'Assertion (A): √2 is an irrational number. Reason (R): The square root of every prime number is irrational.', null, '["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"]'::jsonb, 0, 'Both statements are true, and R is exactly the general fact that makes A true. Assertion-reason items are lost by students who check only whether both are true and forget to ask whether R explains A.', 1, 'medium', 'assertion_reason', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('145c8df7-0858-5f14-b90e-7d94173cca7f', '780256f7-74e7-5c1b-9d3c-8459318b502f', 'Three bells ring at intervals of 9, 12 and 15 minutes. If they ring together at 8:00 a.m., when do they next ring together?', 'A temple has three bells. The first rings every 9 minutes, the second every 12 minutes and the third every 15 minutes. All three are rung together at 8:00 a.m.', '["8:45 a.m.","9:00 a.m.","11:00 a.m.","12:00 noon"]'::jsonb, 2, 'They coincide again after the LCM of the three intervals. 9 = 3², 12 = 2²×3, 15 = 3×5, so LCM = 2²×3²×5 = 180 minutes = 3 hours. 8:00 a.m. + 3 hours = 11:00 a.m. The usual trap is adding the intervals instead of taking the LCM.', 2, 'medium', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
