insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('056acb98-d64e-52af-bf45-15b5ef44a85e', '3fbf2bd0-90ca-54b1-b0bb-15f20e49632f', 'Why do the walls of the left ventricle appear thicker than those of the other chambers?', null, '["It stores more blood","It must pump blood to the whole body at high pressure","It receives blood from the lungs","It contains valves"]'::jsonb, 1, 'The left ventricle pumps oxygenated blood into the aorta and around the entire body, so it needs more muscular force. The right ventricle only pumps to the lungs, which are nearby.', 2, 'medium', 'mcq', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('fb9b3c50-88d9-52f6-8859-3fd627165e63', '3fbf2bd0-90ca-54b1-b0bb-15f20e49632f', 'The functional unit of the kidney is the:', null, '["Neuron","Nephron","Alveolus","Villus"]'::jsonb, 1, 'Nephron — kidney. Neuron — nervous system. Alveolus — lungs. Villus — small intestine. These four are deliberately confused in MCQs, so keep them separated.', 1, 'easy', 'mcq', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
insert into public.quiz_questions (id, quiz_id, prompt, stimulus, options, correct_index, explanation, marks, difficulty, question_type, sort_order) values ('b838a8b3-b0ea-57fd-9775-922bc6ea934e', '3fbf2bd0-90ca-54b1-b0bb-15f20e49632f', 'Identify the process and explain the observation.', 'A potted plant is kept in the dark for 48 hours, then one leaf is partly covered with black paper and the plant is placed in sunlight for six hours. The leaf is tested with iodine.', '["The whole leaf turns blue-black because starch is present throughout","Only the uncovered part turns blue-black, showing light is necessary for photosynthesis","Only the covered part turns blue-black","No part turns blue-black because the plant was destarched"]'::jsonb, 1, 'Destarching first removes existing starch, so any starch found afterwards must be newly made. Only the part that received light makes starch, so only that part turns blue-black with iodine. The experiment proves light is essential.', 3, 'medium', 'case_study', 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation;
